using System.IdentityModel.Tokens.Jwt; using MediDesk.Api.Authorization; using MediDesk.Business.Interfaces; using MediDesk.Common.Contracts.Catalog; using MediDesk.Common.Contracts.Operations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace MediDesk.Api.Controllers;
[ApiController][Route("api/returns")] public sealed class ReturnsController(IReturnService s):ControllerBase { [HttpGet][Authorize(Policy=PermissionPolicies.ReturnsView)] public async Task<ActionResult<PagedResponse<SaleReturnDto>>> Get([FromQuery] ReturnQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct)); [HttpPost("sales")][Authorize(Policy=PermissionPolicies.ReturnsAdd)] public async Task<ActionResult<SaleReturnDto>> Create(CreateSaleReturnRequest r,CancellationToken ct){try{var x=await s.CreateSaleReturnAsync(r,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}catch(ArgumentException e){return BadRequest(new ProblemDetails{Title=e.Message});}catch(KeyNotFoundException e){return NotFound(new ProblemDetails{Title=e.Message});}catch(InvalidOperationException e){return Conflict(new ProblemDetails{Title=e.Message});}} }

